import { ViewTransition } from 'react'

const navTransitions = {
  'nav-forward': 'nav-forward',
  'nav-back': 'nav-back',
  default: 'none',
} as const

export function PageTransition({ children }: { children: React.ReactNode }) {
  return (
    <ViewTransition
      enter={navTransitions}
      exit={navTransitions}
      default="none"
    >
      {children}
    </ViewTransition>
  )
}

